import {readFileSync} from 'node:fs';
import {expect, it} from 'vitest';
import {
  countSegmentCrossings,
  isInsideRule,
  rayCrossesEdge,
  segmentCrossesEdge
} from './zone-crossing-rule';

// Oracle: zone-crossing-rule-fixture.json, generated by
// scratchpad/fix/work/W2A/zones/gen.py with shapely 2.2.0 (GEOS 3.14.1): the track is moved by
// (-1e-6^2, -1e-6) and tested with `contains` / `LineString.intersection(boundary)` against integer
// polygons on a 0..8 grid.
const fixture = JSON.parse(
  readFileSync(new URL('./zone-crossing-rule-fixture.json', import.meta.url), 'utf8')
) as {
  polygons: number[][][];
  cases: [polygon: number, track: number[], inside: number[], crossings: number[]][];
};

const flatten = (polygon: number[][]) => polygon.flat();

it('zone boundary rule: a track touching a polygon apex from outside has no crossing', () => {
  const triangle = [0, 10, 5, 0, 10, 10];
  expect(countSegmentCrossings([0, 0], [10, 0], [triangle])).toBe(0);
});

it('zone boundary rule: a track vertex turning back on an edge has no crossing', () => {
  // Polygon above y = 0; the track touches the edge from below.
  const square = [0, 0, 10, 0, 10, 10, 0, 10];
  const crossings =
    countSegmentCrossings([0, -5], [5, 0], [square]) +
    countSegmentCrossings([5, 0], [10, -5], [square]);
  expect(crossings).toBe(0);
});

it('zone boundary rule: a track through a vertex into the interior crosses once', () => {
  const square = [0, 0, 10, 0, 10, 10, 0, 10];
  // From outside through the corner (0, 0) to the interior.
  expect(countSegmentCrossings([-5, -5], [0, 0], [square])).toBe(0);
  expect(countSegmentCrossings([0, 0], [5, 5], [square])).toBe(1);
  expect(countSegmentCrossings([-5, -5], [5, 5], [square])).toBe(1);
  // Through the apex of the triangle from the top into its interior stays consistent with inside().
  const triangle = [0, 10, 5, 0, 10, 10];
  expect(countSegmentCrossings([5, -5], [5, 5], [triangle])).toBe(1);
});

it('zone boundary rule: a track along an edge then leaving crosses once', () => {
  const square = [0, 0, 10, 0, 10, 10, 0, 10];
  // Along the bottom edge (outside under the rule), then up into the square.
  const crossings =
    countSegmentCrossings([-5, 0], [5, 0], [square]) +
    countSegmentCrossings([5, 0], [8, 5], [square]);
  expect(crossings).toBe(1);
  expect(isInsideRule([5, 0], [square])).toBe(false);
  expect(isInsideRule([8, 5], [square])).toBe(true);
});

it('zone boundary rule: collinear overlap and zero-length segments never cross', () => {
  expect(segmentCrossesEdge([0, 0], [4, 0], [1, 0], [3, 0])).toBe(false);
  expect(segmentCrossesEdge([2, 2], [2, 2], [0, 0], [4, 4])).toBe(false);
  expect(rayCrossesEdge([1, 5], [0, 0], [0, 4])).toBe(false);
});

it('zone boundary rule: segment crossing parity equals the inside change on shapely truth', () => {
  expect(fixture.cases.length).toBeGreaterThanOrEqual(2000);
  let tieCases = 0;
  for (const [polygonIndex, track, inside, crossings] of fixture.cases) {
    const rings = [flatten(fixture.polygons[polygonIndex])];
    const points: [number, number][] = [];
    for (let index = 0; index < track.length; index += 2) {
      points.push([track[index], track[index + 1]]);
    }
    for (const [index, point] of points.entries()) {
      expect(
        isInsideRule(point, rings),
        `inside ${polygonIndex} ${points.join(' ')} #${index}`
      ).toBe(inside[index] === 1);
    }
    for (let segment = 0; segment + 1 < points.length; segment++) {
      const count = countSegmentCrossings(points[segment], points[segment + 1], rings);
      expect(count, `crossings ${polygonIndex} ${points.join(' ')} #${segment}`).toBe(
        crossings[segment]
      );
      expect(count % 2).toBe(inside[segment] ^ inside[segment + 1]);
      if (count > 1) {
        tieCases++;
      }
    }
  }
  expect(tieCases).toBeGreaterThan(0);
});
